import{_ as l,l as o,o as e,c as n,v as t,p as E,x as i,d as h,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"后道波长分层","description":"","frontmatter":{"title":"后道波长分层","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/beol-wavelength-mix.md","filePath":"litho/beol-wavelength-mix.md","lastUpdated":1789023840000}'),A={name:"litho/beol-wavelength-mix.md"};function d(m,a,c,B,_,F){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="后道波长分层" tabindex="-1">后道波长分层 <a class="header-anchor" href="#后道波长分层" aria-label="Permalink to &quot;后道波长分层&quot;">​</a></h1><div class="epigraph"><p>后道不是一层金属用一台最贵的扫描机。节距、胶厚、套刻与成本把 i 线、KrF、ArF 甚至 EUV 分到不同层上，混用是默认，不是过渡期。</p><footer>—— 对照 Levinson 对多层光刻与波长选择的产线论述</footer></div><p><a href="/litho/contact-hole-patterning">上一课</a>把最紧的孔写成二维成像加高 AR 转印。缺口是：芯片上绝大多数后道层并不是那种孔。金属、通孔、钝化、植球前的厚胶，节距可以差一个数量级。本课钉后道波长分层：i 线 / KrF / ArF 如何按层混用。<a href="/litho/finfet-gaa">FinFET 到 GAA</a> 从下一课起换前道器件拓扑，不再把金属层波长当晶体管微缩。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/litho-wavelengths">波长台阶</a>已经说明 \\(\\lambda\\) 不能微调。若由此推出「先进产品每一层都该 EUV」，后道成本与产能会立刻墙。Levinson 的产线图像是分层：关键前层和最密金属才配短波与高 NA；植入阻挡、厚介质开窗、松节距金属仍用 i 线或 KrF，因为胶可以更厚、焦深更松、机台小时更便宜。</p><p>缺口是选择规则，不是再列一条汞灯到 EUV 的年表。上一课的接触孔工艺只绑定「这一层的节距与缺陷」；后道有十几层金属，必须允许同一片晶圆上多种波长。</p><h3 id="节点名不是后道波长" tabindex="-1">节点名不是后道波长 <a class="header-anchor" href="#节点名不是后道波长" aria-label="Permalink to &quot;节点名不是后道波长&quot;">​</a></h3><p>「7 nm 产品」指前道栅极节距的商品名。后道某层仍可能是 193 nm 浸没多重，或 248 nm 单次。把商品节点写成整片波长，会高估 EUV 层数、低估 DUV 机队。</p><p><span class="marginnote">植入层常用厚胶挡离子。厚胶与 i 线 / KrF 的焦深匹配，强行上 ArF 薄胶并不自动更好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按节距与膜厚选波长，再选 NA 与是否多重。松金属：i 线或 KrF 单次，二元掩模，规则 OPC 即可。中等后道：干式或浸没 ArF，衰减相移，模型基 OPC。最密金属与通孔：浸没多重或 EUV 单次，计算光刻和套刻预算按<a href="/litho/lele-multipattern">多重图形</a>另开。同一后道栈里出现三种波长是常态。</p><p>混机带来匹配套刻：ArF 层对 KrF 层、EUV 对浸没，要对准网格和标记在各波长下都可读。ASML 公开写过 DUV–EUV 交叉匹配；本课只要求分层时把匹配写成预算项，不抄未核对的纳米规格。</p>',12)),(e(),E(p,null,{default:i(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20THK%5B%22%E5%8E%9A%E8%83%B6%20%2F%20%E6%A4%8D%E5%85%A5%20%2F%20%E5%BC%80%E7%AA%97%22%5D%20--%3E%20IL%5B%22i%20%E7%BA%BF%20365%20nm%22%5D%0A%20%20MID%5B%22%E4%B8%AD%E7%AD%89%E9%87%91%E5%B1%9E%20%2F%20%E9%80%9A%E5%AD%94%22%5D%20--%3E%20KRF%5B%22KrF%20248%20nm%22%5D%0A%20%20TGT%5B%22%E8%BE%83%E5%AF%86%E5%90%8E%E9%81%93%22%5D%20--%3E%20ARF%5B%22ArF%20193%20%E5%B9%B2%20%2F%20%E6%B5%B8%E6%B2%A1%22%5D%0A%20%20CRIT%5B%22%E6%9C%80%E5%AF%86%E9%87%91%E5%B1%9E%E4%B8%8E%E5%AD%94%22%5D%20--%3E%20EUV%5B%22EUV%20%E6%88%96%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%22%5D%0A%20%20IL%20--%3E%20MIX%5B%22%E5%90%8C%E4%B8%80%E6%99%B6%E5%9C%86%E5%A4%9A%E5%B1%82%E6%B7%B7%E6%B3%A2%E9%95%BF%22%5D%0A%20%20KRF%20--%3E%20MIX%0A%20%20ARF%20--%3E%20MIX%0A%20%20EUV%20--%3E%20MIX%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="胶与涂显也分层" tabindex="-1">胶与涂显也分层 <a class="header-anchor" href="#胶与涂显也分层" aria-label="Permalink to &quot;胶与涂显也分层&quot;">​</a></h3><p>换波长等于换胶族：DNQ–酚醛对 i 线，CAR 对 KrF/ArF，EUV 另册。涂胶显影轨道的烘箱与显影头按胶族资格认证，不能假设「后道轨道通用」。上一课的孔若在 EUV 胶上过了随机，松通孔仍可能走 ArF 正胶，缺陷模式完全不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分辨率仍是 \\(k_1\\lambda/\\mathrm{NA}\\)。后道把 \\(k_1\\) 用得更松、把 \\(\\lambda\\) 选得更长，换来焦深、胶厚和机台成本。金属电阻与通孔电阻关心的是刻蚀后的开口和填充，不是每一层都逼近单次曝光地板。分层的机制是：<strong>电学关键路径上的节距</strong>才配短波；其余层的优化目标是缺陷、产率和与前层的套刻。</p><p>混波长的代价是工件台、镜头指纹和热负荷各不相同，产品套刻要把设备项按层配对。Chiplet 不取消这张表：每颗裸片内部后道仍然分层。</p><p><span class="marginnote">「后道已经不用光刻」是封装口头禅。中介层和 RDL 另有一套线宽，仍然是光刻；只是波长更老、胶更厚。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把某代工厂未公开的「EUV 用了几层」写成行业定律。本课只给分层逻辑：节距、胶厚、套刻、成本。不要在这里重讲 GAA 释放。也不要把 i 线写成已被淘汰——厚胶层还在用。出口管制卡住的是先进扫描机，成熟波长的后道仍可扩产，与<a href="/litho/china-litho-supply-chain">国产替代</a>的档位叙事一致，本课不重写供应商名单。</p><p><span class="marginnote">出处：Harry J. Levinson, <em>Principles of Lithography</em>（SPIE）对多层工艺与工具选择的讨论；波长台阶见 Mack 与产线公开机队混用。不编造某厂 BEOL 层数表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后道按层选 i 线、KrF、ArF、EUV，混用是默认。</li><li>商品节点不等于每一层的曝光波长。</li><li>厚胶与松节距优先更长波长和更大焦深。</li><li>混机套刻与涂显资格是分层的隐藏成本。</li><li>前道器件拓扑下一课，本课停在金属/通孔波长。</li><li>出处：Levinson 光刻原理；波长与机队公开分层逻辑。</li></ul>',11))])}const b=l(A,[["render",d]]);export{u as __pageData,b as default};
